css:
.fx-mq{width:min(1180px,100%);display:grid;gap:2.2em;text-align:center}
.fx-mq h2{font-size:clamp(1.8em,4vw,2.6em)}
.fx-mq .row{overflow:hidden;-webkit-mask-image:linear-gradient(90deg,transparent,#000 12%,#000 88%,transparent);mask-image:linear-gradient(90deg,transparent,#000 12%,#000 88%,transparent)}
.fx-mq .track{display:flex;gap:1em;width:max-content;animation:fxmq calc(32s/var(--speed)) linear infinite}
.fx-mq .row.rev .track{animation-direction:reverse}.fx-mq .row:hover .track{animation-play-state:paused}
.fx-mq .logo{display:inline-flex;align-items:center;gap:.6em;padding:.8em 1.4em;border:1px solid var(--border);border-radius:999px;background:color-mix(in srgb,var(--surface) 94%,var(--text));font:600 1.05em var(--font-heading);white-space:nowrap}
.fx-mq .logo i{width:.9em;height:.9em;border-radius:30%;background:var(--accent)}.fx-mq .logo:nth-child(3n) i{background:var(--primary);border-radius:50%}.fx-mq .logo:nth-child(3n+1) i{border-radius:0;transform:rotate(45deg)}
@keyframes fxmq{to{transform:translateX(calc(-50% - .5em))}}
@media(prefers-reduced-motion:reduce){.fx-mq .track{animation:none}}
/* touch: :hover mirrored as .is-tap */
.fx-mq .row.is-tap .track{animation-play-state:paused}
